package com.andye.warmod.radar.station.client;import com.mojang.blaze3d.vertex.*;import net.minecraft.client.renderer.texture.OverlayTexture;public final class RadarDishMesh {private RadarDishMesh(){}public static void render(PoseStack.Pose p,VertexConsumer b,int light,boolean warning){int segments=20,rings=6;float radius=1.2f;for(int ring=0;ring<rings;ring++){float r1=radius*ring/rings,r2=radius*(ring+1)/rings;float z1=-.28f*(r1/radius)*(r1/radius),z2=-.28f*(r2/radius)*(r2/radius);for(int i=0;i<segments;i++){double a=Math.PI*2*i/segments,n=Math.PI*2*(i+1)/segments;quad(p,b,(float)Math.cos(a)*r1,(float)Math.sin(a)*r1,z1,(float)Math.cos(a)*r2,(float)Math.sin(a)*r2,z2,(float)Math.cos(n)*r2,(float)Math.sin(n)*r2,z2,(float)Math.cos(n)*r1,(float)Math.sin(n)*r1,z1,104,111,112,light);}}box(p,b,-.08f,-.08f,-.65f,.08f,.08f,.45f,64,68,70,light);box(p,b,-.14f,-.14f,.38f,.14f,.14f,.60f,warning?210:205,warning?35:140,25,15728880);}
 private static void box(PoseStack.Pose p,VertexConsumer b,float x1,float y1,float z1,float x2,float y2,float z2,int r,int g,int bl,int l){quad(p,b,x1,y1,z1,x2,y1,z1,x2,y2,z1,x1,y2,z1,r,g,bl,l);quad(p,b,x2,y1,z2,x1,y1,z2,x1,y2,z2,x2,y2,z2,r,g,bl,l);quad(p,b,x1,y1,z2,x1,y1,z1,x1,y2,z1,x1,y2,z2,r,g,bl,l);quad(p,b,x2,y1,z1,x2,y1,z2,x2,y2,z2,x2,y2,z1,r,g,bl,l);}private static void quad(PoseStack.Pose p,VertexConsumer b,float ax,float ay,float az,float bx,float by,float bz,float cx,float cy,float cz,float dx,float dy,float dz,int r,int g,int bl,int l){v(p,b,ax,ay,az,0,0,r,g,bl,l);v(p,b,bx,by,bz,1,0,r,g,bl,l);v(p,b,cx,cy,cz,1,1,r,g,bl,l);v(p,b,dx,dy,dz,0,1,r,g,bl,l);}private static void v(PoseStack.Pose p,VertexConsumer b,float x,float y,float z,float u,float v,int r,int g,int bl,int l){b.addVertex(p,x,y,z).setColor(r,g,bl,255).setUv(u,v).setOverlay(OverlayTexture.NO_OVERLAY).setLight(l).setNormal(p,0,0,1);}}